describe('Notification Count Reset', () => {
    beforeEach(() => {
        cy.visit('/notifications');
        cy.login(); // Assuming there's a custom command for login
    });

    it('should display notification count reset to zero after reading all messages', () => {
        cy.get('.notification-count').should('have.text', '3'); // Assuming there are 3 notifications initially
        cy.get('.notification-item').each(($el) => {
            cy.wrap($el).click(); // Simulate reading each notification
        });
        cy.get('.notification-count').should('have.text', '0'); // Verify count is reset to zero
    });

    it('should not show negative notification count after reading all messages', () => {
        cy.get('.notification-count').should('have.text', '3'); // Assuming there are 3 notifications initially
        cy.get('.notification-item').each(($el) => {
            cy.wrap($el).click(); // Simulate reading each notification
        });
        cy.get('.notification-count').should('have.text', '0'); // Verify count is reset to zero
        cy.get('.notification-item').first().click(); // Click again to simulate reading already read notification
        cy.get('.notification-count').should('have.text', '0'); // Ensure count remains zero
    });
});
